const eventbriteRaw = $('Fetch Eventbrite Events').first().json.events || [];
const meetupRaw = $('Fetch Meetup Events').first().json.events || [];

const categories = ($env.INTEREST_CATEGORIES || 'music,tech,food,art,outdoor').split(',').map(c => c.trim().toLowerCase());

function normalizeEventbrite(e) {
  const name = e.name?.text || '';
  const desc = e.description?.text || '';
  const cat = (e.category?.short_name || '').toLowerCase();
  const venueName = e.venue?.name || '';
  const venueAddress = e.venue?.address?.localized_address_display || '';
  const startDate = e.start?.local || '';
  const isFree = e.is_free || false;
  const url = e.url || '';
  return { source: 'eventbrite', name, desc, cat, venueName, venueAddress, startDate, isFree, url };
}

function normalizeMeetup(e) {
  const name = e.name || '';
  const desc = (e.description || '').replace(/<[^>]+>/g, '').slice(0, 300);
  const cat = (e.group?.category?.shortname || '').toLowerCase();
  const venueName = e.venue?.name || 'Online / TBD';
  const venueAddress = e.venue ? `${e.venue.address_1 || ''}, ${e.venue.city || ''}` : '';
  const startDate = e.local_date ? `${e.local_date}T${e.local_time || '00:00'}` : '';
  const isFree = e.fee == null || e.fee.amount === 0;
  const url = e.link || '';
  return { source: 'meetup', name, desc, cat, venueName, venueAddress, startDate, isFree, url };
}

const allEvents = [
  ...eventbriteRaw.map(normalizeEventbrite),
  ...meetupRaw.map(normalizeMeetup)
];

// Filter to relevant categories
const filtered = allEvents.filter(e => {
  const text = (e.name + ' ' + e.desc + ' ' + e.cat).toLowerCase();
  return categories.some(c => text.includes(c));
});

// Sort by date
filtered.sort((a, b) => new Date(a.startDate) - new Date(b.startDate));

// Deduplicate by similar name (simple)
const seen = new Set();
const deduped = filtered.filter(e => {
  const key = e.name.toLowerCase().slice(0, 40);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return [{ json: { events: deduped.slice(0, 30), total: deduped.length, city: $env.CITY_NAME } }];

