const newsletterMd = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const eventsData = $('Merge & Filter Events').first().json;

// Convert basic markdown to HTML
function mdToHtml(md) {
  return md
    .replace(/^### (.+)$/gm, '<h3>$1</h3>')
    .replace(/^## (.+)$/gm, '<h2>$1</h2>')
    .replace(/^# (.+)$/gm, '<h1>$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/^- (.+)$/gm, '<li>$1</li>')
    .replace(/(<li>.*<\/li>\n?)+/g, s => `<ul>${s}</ul>`)
    .replace(/\n\n/g, '</p><p>')
    .replace(/^(?!<[hul])/gm, '')
    .replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2" style="color:#d4622a">$1</a>');
}

const contentHtml = mdToHtml(newsletterMd);
const weekOf = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric' });

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <style>
    @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Source+Serif+4:ital,wght@0,400;0,600;1,400&display=swap');
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { background: #f4efe8; font-family: 'Source Serif 4', Georgia, serif; color: #2a2a2a; }
    .wrapper { max-width: 600px; margin: 0 auto; background: #fffdf8; }
    .masthead { background: #1c1c1c; color: #f4efe8; padding: 32px 40px; }
    .masthead h1 { font-family: 'Playfair Display', Georgia, serif; font-size: 28px; letter-spacing: -0.5px; }
    .masthead .edition { color: #a89880; font-size: 13px; margin-top: 6px; }
    .body { padding: 36px 40px; }
    .body p { font-size: 16px; line-height: 1.75; margin-bottom: 16px; }
    .body h2 { font-family: 'Playfair Display', Georgia, serif; font-size: 20px; color: #1c1c1c; margin: 32px 0 12px; border-bottom: 1px solid #e8e0d5; padding-bottom: 6px; }
    .body h3 { font-size: 16px; font-weight: 600; color: #1c1c1c; margin: 20px 0 6px; }
    .body ul { padding-left: 20px; margin-bottom: 16px; }
    .body li { font-size: 15px; line-height: 1.65; margin-bottom: 8px; }
    .body strong { font-weight: 600; }
    .footer { background: #1c1c1c; color: #888; font-size: 12px; padding: 20px 40px; text-align: center; }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="masthead">
      <h1>What's On in ${eventsData.city}</h1>
      <div class="edition">Week of ${weekOf} · ${eventsData.total} events found · curated by AI</div>
    </div>
    <div class="body">
      <p>${contentHtml}</p>
    </div>
    <div class="footer">You're receiving this because you set this up. Events sourced from Eventbrite & Meetup. Not affiliated with any event organizer.</div>
  </div>
</body>
</html>`;

const subject = `What's on in ${eventsData.city} this week (${weekOf})`;

return [{ json: { html, subject } }];
